FREE_VAR_MISMATCH = 'Gold has 3 free variable(s) (e2 : EMP_FNAME, c6 : CRS_DESCRIPTION, p1 : PROF_OFFICE) but Predicted has 2 (e2 : EMP_FNAME, p2 : PROF_OFFICE): their answers have different arities'
