# ---------- run-time logging (stages R1-R4) ----------
#
# Switched on when this file is run:  -v | -vv | --log FILE | --timings.
# The log FILE always gets full detail.  Nothing here depends on how the
# file was generated, so the generated file stays byte-identical.

import sys as _sys
import time as _time

_RUN_STAGES = {
    "R1": "assemble background",
    "R2": "check gold |= predicted",
    "R3": "check predicted |= gold",
    "R4": "verdict",
}


class _RunLog:
    def __init__(self):
        self.level, self.fh, self.timings = 0, None, False
        self.cur, self.t0, self.failed = None, 0.0, False

    def configure(self, argv):
        import argparse
        ap = argparse.ArgumentParser(
            description="Run this generated equivalence check.")
        ap.add_argument("-v", "--verbose", action="count", default=0,
                        help="-v: stage summaries; -vv: full detail")
        ap.add_argument("--log", metavar="FILE",
                        help="write the log to FILE (always full detail)")
        ap.add_argument("--log-append", action="store_true",
                        help=argparse.SUPPRESS)
        ap.add_argument("--timings", action="store_true",
                        help="add per-stage and per-attempt durations")
        a = ap.parse_args(argv)
        self.level, self.timings = a.verbose, a.timings
        if self.level and hasattr(_sys.stderr, "reconfigure"):
            _sys.stderr.reconfigure(encoding="utf-8", errors="replace")
        if a.log:
            self.fh = open(a.log, "a" if a.log_append else "w",
                           encoding="utf-8", newline="\n")
            if a.log_append:
                self.fh.write("\n")
            else:
                self.fh.write("check log\n  file    : %s\n\n" % _sys.argv[0])

    def wants(self, level):
        return self.fh is not None or self.level >= level

    def _emit(self, level, msg):
        if self.level >= level:
            print(msg, file=_sys.stderr)
        if self.fh is not None:
            self.fh.write(msg + "\n")

    def heading(self, msg):
        self._emit(1, msg)

    def info(self, msg):
        self._emit(1, "   " + msg)

    def detail(self, msg):
        self._emit(2, "      " + msg)

    def stage(self, sid):
        self.done()
        self.cur, self.t0 = sid, _time.perf_counter()
        self._emit(1, "== [%s] %s" % (sid, _RUN_STAGES[sid]))

    def done(self):
        if self.cur is not None and self.timings:
            self._emit(1, "   [%s] took %.3f s"
                       % (self.cur, _time.perf_counter() - self.t0))
        self.cur = None

    def fail(self, exc):
        if self.failed:
            return
        self.failed = True
        where = ("stage [%s] %s" % (self.cur, _RUN_STAGES[self.cur])
                 if self.cur else "before the first stage")
        self._emit(0, "!! FAILED in %s: %s: %s"
                   % (where, type(exc).__name__, exc))
        if self.fh is not None:
            import traceback
            self.fh.write("".join(traceback.format_exception(
                type(exc), exc, exc.__traceback__)))
        self.cur = None

    def close(self):
        self.done()
        if self.fh is not None:
            self.fh.close()
            self.fh = None


_LOG = _RunLog()


def main(argv=None):
    _LOG.configure(_sys.argv[1:] if argv is None else argv)
    _LOG.heading("==== checking ====")
    try:
        _LOG.stage("R4")
        _LOG.info("R1-R3 skipped: the free variables decide the verdict")
        _LOG.info("mismatch: %s" % FREE_VAR_MISMATCH)
        if FREE_VAR_WARNINGS:
            for w in FREE_VAR_WARNINGS:
                _LOG.info("WARNING: %s" % w)
        print("[free variables] mismatch: %s" % FREE_VAR_MISMATCH)
        for w in FREE_VAR_WARNINGS:
            print("[free variables] warning: %s" % w)
        print()
        verdict = "NOT EQUIVALENT"
        print("VERDICT: %s (free-variable mismatch)" % verdict)
        _LOG.info("VERDICT: %s (free-variable mismatch)" % verdict)
        _LOG.done()
        return verdict
    except Exception as exc:
        _LOG.fail(exc)
        raise
    finally:
        _LOG.close()


if __name__ == "__main__":
    main()
